import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize the pool to set feeRate to 1000 (within valid range)
        // We need to be the owner (this contract) so the onlyOwner check passes
        c.initialize(
            address(0),   // baseToken
            address(0),   // nft
            1000 ether,   // virtualBaseTokenReserves (128 bits)
            1000,         // virtualNftReserves (128 bits)
            100,          // changeFee (56 bits)
            1000,         // feeRate (16 bits, valid <= 5000)
            bytes32(0),   // merkleRoot
            false,        // useStolenNftOracle
            false         // payRoyalties
        );
        uint256 oldFeeRate = c.feeRate();
        // Try to set feeRate to 6000 (> 5000, should revert in reference)
        // Use try/catch to catch the revert
        bool setSucceeded;
        try c.setFeeRate(6000) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }
        // The reference reverts, so setSucceeded is false; the bug does not revert, so setSucceeded is true
        // After that, call availableForFlashLoan (it does not affect feeRate, so the difference persists)
        // We need to mint an nft first so availableForFlashLoan doesn't fail for other reasons
        // But availableForFlashLoan is a view, so we can just call it
        (bool success, ) = address(c).staticcall(abi.encodeWithSignature("availableForFlashLoan(address,uint256)", address(0), 1));
        c.availableForFlashLoan(address(0), 1); // just to satisfy call sequence
        // Now check that the feeRate changed if and only if the setSucceeded
        bool feeRateChanged = c.feeRate() != oldFeeRate;
        // The reference: setSucceeded is false, feeRateChanged is false
        // The bug: setSucceeded is true, feeRateChanged is true
        // They diverge: reference has setSucceeded == false && feeRateChanged == false
        // Bug has setSucceeded == true && feeRateChanged == true
        // We assert that setSucceeded and feeRateChanged are equal
        assertTrue(setSucceeded == feeRateChanged, "Property: setSucceeded should match feeRateChanged");
    }
}

